#ifndef ROB_PRF_H
#define ROB_PRF_H

#include <stdint.h>

typedef uint64_t (*rob_kernel_fn)(void **chain_a, void **chain_b, uint64_t iters);

struct rob_kernel {
    const char *kind; /* nop | int | vec | mix */
    int n;            /* filler instructions between the two missing loads */
    rob_kernel_fn fn;
};

/* Generated by gen_kernels.py into build/rob_prf_table.c */
extern const struct rob_kernel rob_kernels[];
extern const int rob_nkernels;

#endif
